"""Authored adult relationships, household friendships and practical rituals."""

def beat(title, opening, gentle, playful, gentle_label="Ask her to explain", playful_label="Respond playfully"):
    return {'title':title,'opening':opening,'choices':{'gentle':{'label':gentle_label,'response':gentle},'playful':{'label':playful_label,'response':playful}}}

# Each route is playable using the starting common room/library after recruitment.
# Specialist-room content is an additional route, never a wardrobe bottleneck.
